    /// The examples that came with the first versions, which a library that was set up then already has.
    static let originalFolders: [String] = ["Halo and Horns.backdroplens", "Heart Eyes.backdroplens", "Golden Hour.backdroplens",
                                            "Bubble Talk.backdroplens", "Name Tag.backdroplens"]

    /// Writes the samples and a readme into `directory`, leaving anything already there alone.
    static func install(into directory: URL) throws { try install(all, into: directory) }

    /// The same for just some of the samples: the ones a later version added, for a folder that was set up by an earlier one.
    static func install(_ samples: [(folder: String, json: String)], into directory: URL) throws {
        let fm = FileManager.default
        try fm.createDirectory(at: directory, withIntermediateDirectories: true)
        let readmeURL = directory.appendingPathComponent("README.txt")
        if !fm.fileExists(atPath: readmeURL.path) { try readme.write(to: readmeURL, atomically: true, encoding: .utf8) }
        for sample in samples {
            let folder = directory.appendingPathComponent(sample.folder, isDirectory: true)
            guard !fm.fileExists(atPath: folder.path) else { continue }
            try fm.createDirectory(at: folder, withIntermediateDirectories: true)
            try sample.json.write(to: folder.appendingPathComponent("lens.json"), atomically: true, encoding: .utf8)
        }
    }
}
